            + IS.lines.map(l => l.sp === 'X' ? `- \`${pad(Math.floor(l.t / 60), 2)}:${pad(l.t % 60, 2)}\` *${l.text}*` : `- \`${pad(Math.floor(l.t / 60), 2)}:${pad(l.t % 60, 2)}\` **${l.name}:** ${l.text}`).join('\n')
            + (IS.statement ? `\n\n## ${T('int_p_statement')}\n\n${IS.statement}` : '');
        const d = { id: nid(), docNo: number('doc', 'DOC', 5), title: T('int_doc_title', IS.subject), type: 'interrogation', source: 'pc', authorId: 'me', author: ME.name, caseId: IS.caseId,
            body, meta: { signatures: [] }, createdAt: now(), updatedAt: now() };
        DOCS.push(d);
