    async function apiCall(name, payload) {
        const fn = A[name];
        if (!fn) { console.warn('[demo] no handler for', name); return { ok: true }; }
        const res = fn(payload || {}) || { ok: true };
        if (res.ok && !res.silent) setTimeout(() => emit('changed', { name }), 30);
        return res;
    }

    async function callback(name, body) {
        switch (name) {
            case 'pcLogin': return payload();
            case 'api': return apiCall(body.name, body.payload);
            case 'srv': { const fn = SRV[body.name]; return fn ? fn(body.payload || {}) : { error: 'invalid' }; }
            case 'pcClose': nui('osClose'); afterClose(); return { ok: true };
            case 'close': afterClose(); return { ok: true };
            case 'notify': demoToast(body.msg, body.type); return { ok: true };
            case 'myLocation': return { x: 213.4, y: -905.2, z: 30.7, street: 'Vespucci Blvd', cross: 'Power St', zone: 'Legion Square' };
            case 'docNearby': return { people: [{ id: 2, name: 'Tony Rossi' }, { id: 4, name: 'Laura Hayes' }] };
            case 'docShow':
                demoToast(`Shown to ${body.target === 2 ? 'Tony Rossi' : 'Laura Hayes'}`);
                setTimeout(() => {
                    const d = Demo.current;
                    if (!d || d.copy) return;
                    const who = body.target === 2 ? 'Tony Rossi' : 'Laura Hayes';
                    d.signatures = (d.signatures || []).concat({ name: who, at: now(), path: 'M30 60L60 40L80 70L110 30L140 65L170 45L200 60' });
                    demoToast(T('doc_signed_by', who));
                    if (!document.getElementById('doc').classList.contains('hidden')) Demo.showDoc(d);
                }, 3500);
                return { ok: true };
            case 'printerDo':
                if (body.action === 'pickup' && TRAY.length) { Demo.showDoc(TRAY.shift()); return { ok: true }; }
                demoToast({ copy: 'Demo: the copy prints - marked as COPY.', scan: 'Demo: scanned into the Police PC.', refill: 'Demo: refilled.' }[body.action] || 'Demo: done.');
                afterClose();
                return { ok: true };
            case 'adminPlace': demoToast('In game: aim with the camera, rotate with the mouse wheel, E = place.'); setTimeout(() => Demo.openAdmin(), 1200); return { ok: true };
            case 'adminTeleport': demoToast('In game you would be teleported to the point.'); return { ok: true };
            case 'askReply': return { ok: true };
            default: return { ok: true };
        }
    }

    const realFetch = window.fetch.bind(window);
    window.fetch = async (url, opts) => {
        const m = String(url).match(/^https:\/\/[\w-]+\/(\w+)$/);
        if (!m) return realFetch(url, opts);
        let body = {};
        try { body = opts && opts.body ? JSON.parse(opts.body) : {}; } catch (e) { /* ignore */ }
        await sleep(40 + Math.random() * 90);
        let out;
        try { out = await callback(m[1], body); } catch (e) { console.error('[demo]', e); out = { error: 'server' }; }
        const data = clone(out === undefined ? { ok: true } : out);
        return { json: async () => data };
    };

